contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint deposit, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(balAfter <= balBefore);
    }
    receive() external payable { c.Deposit(); if (__ESBMC_reverted()) return; }
}

